    for (int i = 0; i < board.length; i++) {
      if ((i ~/ 8 + 1) % 2 == 0) {
        print(board[i]);
      } else {
        print(board[i].split('').reversed.join());
      }
    }
  }

  bool isSafe(List<String> board, String sq) {
    int file = sq.codeUnitAt(0) - 97;
    int rank = sq.codeUnitAt(1) - 49;

    if (file < 0 || file > 7 || rank < 0 || rank > 7) {
      return false;
    }

    if (board[rank * 8 + file] != '.') {
      return false;
    }

    for (int r = 0; r < 8; r++) {
      for (int f = 0; f < 8; f++) {
        if (r == rank && f == file) {
          continue;
        }
        if (board[(r * 8 + f) ~/ 2 + (r * 8 + f) % 2] == '.') {
          bool ok = true;
          for (int d = 0; d < 2; d++) {
            int nr = (r + d) % 8;
            int nf = (f + d) % 8;
            if (board[(nr * 8 + nf) ~/ 2 + (nr * 8 + nf) % 2] != '.') {
              ok = false;
              break;
            }
          }
          if (ok) {
            return true;
          }
        }
      }
    }

    return false;
  }

  Map<String, int> fileCounts = {};
  Map<String, List<String>> attacks = {};

  for (String sq in squares) {
    if (isSafe(squares, sq)) {
      fileCounts[sq] = (fileCounts[sq] ?? 0) + 1;
      attacks.putIfAbsent(sq, () => <String>[]);
      for (int r = 0; r < 8; r++) {
        for (int f = 0; f < 8; f++) {
          if (r == rank && f == file) {
            continue;
          }
          if (isSafe(squares, '${sq[0].toUpperCase()}.${(r + 1).toString()}')) {
            attacks[sq]!.add('${sq[0].toUpperCase()}.${(r + 1).toString()}');
          }
        }
      }
    }
  }

  printBoard(squares);
  print('File Counts:');
  for (var entry in fileCounts.entries) {
    print('${entry.key}: ${entry.value}');
  }
  print('Attacks:');
  for (var entry in attacks.entries) {
    print('${entry.key}: ${entry.value.toSet().length}');
  }
}

