  Map<String, int> cumWinners = {};

  List<MapEntry<int, int>> cumEntries = [];

  void backtrace(int index, int remaining, int s) {
    if (index == n) {

      int s1 = s & 0xF;
      int s2 = ((s >> 4) & 0xF) | ((((s >> 8) & 0xF) << 4) & 0xF);
      int s3 = ((s >> 12) & 0xF) | ((((s >> 16) & 0xF) << 4) & 0xF);
      int s4 = ((s >> 20) & 0xF) | ((((s >> 24) & 0xF) << 4) & 0xF);

