void fn0(List<String> args) {

  final List<String> items = args.isNotEmpty ? args : ['a', 'b', 'c', 'd'];

  final int n = items.length;

  if (n == 0) {
    print('Item set is empty. No valid partitions exist.');
    return;
  }

  final Set<String> itemSet = items.toSet();

  final Map<String, List<String>> itemMap = {};
  for (int i = 0; i < n; i++) {
    final String item = items[i];
    itemMap.putIfAbsent(item, () => []);
    itemMap[item]!.add(item);
  }

  int minItems = n + 1;
  String? bestItem;

  void backtrack(int start, List<String> current, List<String> remaining, Set<String> used) {
    if (remaining.isEmpty) {
      final List<String> partition = List<String>.from(current);
      if (partition.length < minItems) {
        return;
      }

      print(partition);
      if (minItems == n + 1) {
        bestItem = null;
        minItems = partition.length;
      } else if (partition.length < minItems) {
        if (bestItem == null || partition.length < bestItem!.length) {
          bestItem = partition;
        }
      }
      return;
    }

    for (int i = start; i < n; i++) {
      final String item = items[i];

      if (used.contains(item)) {
        continue;
      }

      used.add(item);
      current.add(item);

      final List<String> next = List<String>.from(remaining);
      next.removeAt(0);

      backtrack(i + 1, current, next, used);

      current.removeLast();
      used.remove(item);
    }
  }

  final List<String> used = [];
  backtrack(0, [], items, used);

  if (bestItem != null) {
    print('Best partition found: $bestItem');
  } else {
    print('No valid partitions exist.');
  }
}

