    [24, 25],
    [25, 26],
    [26, 27],
    [27, 28],
    [28, 29],
    [29, 30],
  ];

  int n = requests.length;
  if (n == 0) {
    print('No requests.');
    return;
  }

  List<int> levels = List<int>.filled(n, 0);
  for (int i = 0; i < n; i++) {
    List<int> req = requests[i];
    levels[i] = req[0];
  }

  Map<int, List<int>> buckets = {};
  for (int level in levels) {
    buckets[level] = [];
  }

  for (int i = 0; i < n; i++) {
    List<int> req = requests[i];
    int level = req[0];
    buckets[level]!.add(i);
  }

  void traverse(int level, List<int> path) {
    print('$level: ${buckets[level]}');
    for (int p in path) {
      print('  -> ${levels[p]}');
    }
  }

  List<int> bfs(int level) {
    List<int> queue = [];
    if (buckets[level]!.isEmpty) return [];
    for (int p in buckets[level]!) {
      queue.add(p);
    }
    List<int> result = [];
    while (queue.isNotEmpty) {
      int u = queue.removeAt(0);
      result.add(u);
      List<int> neighbors = buckets[levels[u]]!;
      for (int v in neighbors) {
        queue.add(v);
      }
    }
    return result;
  }

  List<int> current = [0];
  List<int> bfsResult = bfs(levels[0]);
  traverse(levels[0], current);
  for (int i = 1; i < n; i++) {
    List<int> next = bfs(levels[i]);
    current = bfsResult + next;
    traverse(levels[i], current);
  }
}

