  }
  int minX = cells.keys.map((key) => cells[key]!).reduce((a, b) => a < b ? a : b);
  int maxX = cells.keys.map((key) => cells[key]!).reduce((a, b) => a > b ? a : b);
  int minY = cells.keys.map((key) => cells[key]!).reduce((a, b) => a < b ? a : b);
  int maxY = cells.keys.map((key) => cells[key]!).reduce((a, b) => a > b ? a : b);
  List<int> xs = [];
  List<int> ys = [];
  for (var entry in cells.entries) {
    int x = entry.key.split('-').map(int.parse).reduce((a, b) => a < b ? a : b);
    int y = entry.value;
    if (x > minX) {
      xs.add(minX);
    }
    if (x < maxX) {
      xs.add(x);
    }
    if (y > minY) {
      ys.add(minY);
    }
    if (y < maxY) {
      ys.add(y);
    }
  }
  xs.sort();
  ys.sort();
  int cellsCount = 0;
  for (int x = minX; x <= maxX; x++) {
    for (int y = minY; y <= maxY; y++) {
      bool enclosed = false;
      for (int sx = 0; sx < xs.length; sx++) {
        for (int sy = 0; sy < ys.length; sy++) {
          if (xs[sx] <= x && x < xs[sx + 1] &&
              ys[sy] <= y && y < ys[sy + 1]) {
            enclosed = true;
            break;
          }
        }
        if (enclosed) {
          break;
        }
      }
