      print(row.join(' '));
    }
  }

  List<int> charIndices = List.generate(26, (idx) => idx);

  List<int> getCharIndices(String s) {
    List<int> indices = [];
    for (int i = 0; i < s.length; i++) {
      int code = s.codeUnitAt(i);
      indices.add(code - 97);
    }
    return indices;
  }

  List<List<int>> charPositions = [];

  for (int r = 0; r < rows.length; r++) {
    List<int> indices = getCharIndices(rows[r]);
    charPositions.add(indices);
  }

  print('charPositions:');
  printMatrix(charPositions);

  bool isSafe(List<int> p1, List<int> p2) {
    return charPositions[p1[0]][p1[1]] == charPositions[p2[0]][p2[1]];
  }

  List<int> nQueens = List.filled(rows.length, -1);

  bool placeNext(List<int> prev) {
    if (prev.length == rows.length) {
      return true;
    }
    for (int col = 0; col < rows.length; col++) {
      bool ok = false;
      for (int r = prev.length - 1; r >= 0; r--) {
        if (charPositions[r][col] == -1) {
          ok = true;
          break;
        }
      }
      if (!ok) {
        return false;
      }
    }
    nQueens[prev.length] = col;
    return placeNext(prev..add(col));
  }

  placeNext([]);

  print('nQueens:');
  print(nQueens.join(' '));
}

