  if (tideHeights.isEmpty) return false;

  List<int> prefix = List.filled(366, 0);
  for (int i = 0; i < tideHeights.length; i++) {
    prefix[i] = tideHeights[i] + (i > 0 ? prefix[i - 1] : 0);
  }

  int lo = 0;
  int hi = windowSize - 1;
  int best = -1;

  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (prefix[mid] >= tideHeights[startDay]) {
      best = mid;
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }

  if (best == -1) return false;

  lo = best;
  hi = windowSize - 1;
  int endIdx = -1;

  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (prefix[mid] >= tideHeights[startDay + mid]) {
      endIdx = mid;
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }

  return endIdx == -1 ? false : endIdx >= endDay;
}

