  for (String t in targets) {
    targetToBin[t] = t.length.isEven ? 'EVEN' : 'ODD';
  }
  if (targetToBin.isEmpty) return results;

  Map<String, int> freq = {};
  for (String s in logs) {
    freq[s] = (freq[s] ?? 0) + 1;
  }
  if (freq.isEmpty) return results;

  List<MapEntry<String, int>> entries = freq.entries.toList();
  entries.sort((a, b) {
    if (a.value != b.value) return b.value.compareTo(a.value);
    return a.key.compareTo(b.key);
  });

  List<String> validTargets = [];
  for (MapEntry<String, int> entry in entries) {
    String key = entry.key;
    int count = entry.value;
    if (targetToBin[key] == 'EVEN' && count.isEven) {
      validTargets.add(key);
    } else if (targetToBin[key] == 'ODD' && count.isOdd) {
      validTargets.add(key);
    }
  }
  if (validTargets.isEmpty) return results;

  List<List<String>> patterns = [];
  for (String t in validTargets) {
    List<String> candidates = [];
