      if (freq[s] == t.length) {
        candidates.add(s);
      }
    }
    if (candidates.isEmpty) continue;

    String targetBin = targetToBin[t]!;
    List<String> validOrders = [targetBin, 'EVEN', 'ODD', 'ALL'];
    for (String order in validOrders) {
      List<String> validSuffixes = [];
      for (String s in candidates) {
        String suffix = '${s[s.length - t.length]}';
        if (suffix.length <= t.length && t.contains(suffix)) {
          validSuffixes.add(suffix);
        }
      }
      if (validSuffixes.isEmpty) continue;

      List<String> validWords = [];
      for (String s in candidates) {
        for (String suffix in validSuffixes) {
          if (s.length == t.length && s.endsWith(suffix)) {
            validWords.add(s);
            break;
          }
        }
      }
      if (validWords.isNotEmpty) {
        patterns.add([validWords, order]);
      }
    }
  }

  for (List<String> pattern in patterns) {
    String order = pattern[1];
    for (String word in pattern[0]) {
      String result = order == 'ALL' ? word : '${order}_${word[0]}';
      results.add(result);
    }
  }
  return results;
}

