  for (int i = 0; i < events.length; i++) {
    final String event = events[i];
    final int t = times[i];
    if (event == '!') {
      if (stack.isNotEmpty) {
        final String top = stack.removeLast();
        active[top] = 0;
        undoTimes.add(t);
      }
    } else if (event == '?' || event == '<') {
      if (stack.isEmpty) return false;
      final String top = stack.removeLast();
      if (active.containsKey(top)) {
        active[top] = 0;
      } else {
        active[top] = t;
        if (top == initial) hasDuration = true;
      }
    } else if (event == '/') {
      if (stack.isEmpty) return false;
      final String top = stack.removeLast();
      active[top] = 0;
      undoTimes.add(t);
    } else {
      stack.add(event);
      active[event] = t;
      visited.add(event);
    }
  }

  if (!visited.contains(initial)) return false;
  if (!hasDuration) return false;

  final List<String> order = [];
  for (final String s in stack) {
    if (active.containsKey(s)) {
      order.add(s);
    }
  }

  return order.isEmpty || order.length != stack.length;
}

