              timestamps.add('$total-');
              durations.add(0);
            }
          } else {
            timestamps.add('$total');
            durations.add(duration - total);
          }
        } else {
          timestamps.add(token);
          durations.add(int.parse(t));
        }
      }

      final query2 = StringBuffer();
      for (var i = 0; i < count; i++) {
        final ts = timestamps[i];
        final d = durations[i];
        if (ts == d) {
          query2.write('$ts ');
        } else {
          query2.write('$ts->$d ');
        }
      }

      append(query2.toString());
    }
  }

