void fn0(List<String> args) {

  if (args.isEmpty) {
    print('Usage: dart fn0.dart <list of shelf codes> [column-max-len]');
    print('  The script reads the list from stdin (or args[0] if args[0] exists) and');
    print('  outputs the largest word in each line.  A line is split by the first ');
    print('  whitespace character.  If [column-max-len] is given, words longer than');
    print('  [column-max-len] characters are truncated at the end.');
    print('  The default [column-max-len] is 0 (no truncation).');
    return;
  }

  final String? input = args.isNotEmpty ? args[0] : null;

  final int? maxLen = args.length >= 2
      ? int.tryParse(args[1])
      : null;

  final String? target = args.length >= 3
      ? args[2]
      : null;

  final List<String> lines = input == null
      ? <String>[]
      : input.isEmpty
          ? <String>[]
          : input.split('\n');

  int maxLenWithTarget = 0;
  String targetWord = '';

  for (final String line in lines) {
    final parts = line.isEmpty
        ? <String>[]
        : line.split(maxLen == null ? '' : '|');

    String longest = '';
    int bestLen = 0;
    bool found = false;

    for (final String part in parts) {
      if (part.isEmpty) continue;

      if (part.length > bestLen) {
        bestLen = part.length;
        longest = part;
        found = true;
      } else if (part.length == bestLen && part.length > 0) {

        final int cmp = target != null && part.contains(target)
            ? target.compareTo(part)
            : part.compareTo(longest);

        if (cmp < 0) {
          longest = part;
        } else if (cmp == 0 && part.length > longest.length) {
          longest = part;
        }
      }
    }

    if (found) {
      if (maxLenWithTarget < bestLen) {
        maxLenWithTarget = bestLen;
        targetWord = longest;
      }
    }
  }

  print(maxLenWithTarget == 0
      ? 'No word found that contains "$target"'
      : targetWord);
}

