void fn0(List<String> args) {
  if (args.length < 2) {
    print('Usage: <start> <end> [step] [limit]');
    print('  <start> <end> = start to end (inclusive)');
    print('  [step] = between start and end, step by step');
    print('  [limit] = limit total energy used');
    return;
  }

  int start = int.parse(args[0]);
  int end = int.parse(args[1]);
  int? step = int.tryParse(args[2]);
  int? limit = int.tryParse(args[3]);

  int total = start;
  int remaining = end - start;
  String log = '';

  void search(int depth, int energy, int remaining) {
    if (remaining <= 0) {
      if (energy <= limit) {
        if (log.isEmpty) {
          print(total);
        } else {
          print(log);
        }
      }
      return;
    }

    String row = '';
    for (int s = 0; s < depth; s++) {
      row += ' ';
    }

    int used = energy + (remaining - 1) * step!;
    if (used > limit) {
      used = limit;
    }

    if (remaining == 1) {
      if (energy <= limit) {
        log += '$row$total';
      }
    } else {
      if (energy <= limit) {
        log += '$row$total(${used}%)';
      }
      search(depth + 1, used, remaining - 1);
    }
  }

  search(0, 0, remaining);
}

