void fn0(List<String> args) {
  if (args.isEmpty) {
    print('Usage: dart fn0.dart [number] [number] ...');
    print('The result is the number with the fewest digits.');
    return;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  int parse(String s) {
    if (s.isEmpty) return 0;
    int r = int.parse(s.trim());
    return r;
  }

  List<int> argsAsInts = args.map(parse).toList();
  if (argsAsInts.length < 2) {
    print('At least two numbers required.');
    return;
  }

  int minDigit = 10;
  int currentSum = 0;
  int currentCount = 0;

  for (int a in argsAsInts) {
    int aDigit = a.abs();
    if (aDigit < minDigit) {
      minDigit = aDigit;
      currentSum = a;
      currentCount = 1;
    } else if (aDigit == minDigit) {
      currentSum += a;
      currentCount++;
    }
  }

  if (currentCount == 1) {
    print('$currentSum');
  } else {
    int g = gcd(currentSum, minDigit);
    print('$currentSum/$minDigit = $g');
  }
}

