class Polygon extends Shape {
  final List<Point> points;

  const Polygon(this.points);

  @override
  double get area => _computeArea(points);

  double _computeArea(List<Point> points) {
    double sum = 0.0;
    for (int i = 0; i < points.length; i++) {
      sum += points[(i + 1) % points.length].x * points[i].y -
          points[i].x * points[(i + 1) % points.length].y;
    }
    return sqrt(sum);
  }

  @override
  String toString() => 'Polygon:${_computeArea(points)}';
}

