      int maxA = a[0] > a[1] ? a[0] : a[1];
      int maxB = b[0] > b[1] ? b[0] : b[1];
      if (leftMax + rightMax <= remainingSize) {
        return backtrack(i + 2, remainingSize - maxA - maxB);
      }
