      int bucket = d % 9 + 1;
      counts.add(bucket);
    }
    return counts;
  }

  for (String word in words) {
    print(word);
    print('Sum: ${digitSum(word)}');
    print('Bucket Counts: ${bucketCounts(word)}');
    print('');
  }
}

