List<int> fn0(int totalSeats, List<int> requests) {
  if (totalSeats <= 0 || requests.isEmpty) {
    return List.filled(requests.length, 0);
  }
  List<int> counts = List.filled(requests.length, 0);
  int lo = 0;
  int hi = requests.length - 1;
  int ans = 0;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    int target = requests[mid];
    int left = 0;
    int right = totalSeats - 1;
    while (left <= right) {
      int seat = left + (right - left) ~/ 2;
      if (seat >= target) {
        break;
      }
      if (seat < target) {
        left = seat + 1;
      } else {
        right = seat - 1;
      }
    }
    if (right >= 0 && requests[right] == target) {
      hi = mid - 1;
    } else {
      lo = mid + 1;
      ans += seat + 1;
    }
  }
  for (int i = 0; i < requests.length; i++) {
    counts[i] = ans + i;
  }
  return counts;
}

