List<int> fn0(List<int> seeds, int tournamentSeed) {
  if (seeds.isEmpty || tournamentSeed < 1 || tournamentSeed > seeds.length) {
    return List.filled(seeds.length, 0);
  }
  List<int> roundScores = List.filled(seeds.length, 0);
  int round = 1;
  int currentSeed = tournamentSeed;
  while (currentSeed > 1) {
    int nextRound = currentSeed ~/ 2;
    int opponent = currentSeed;
    int opponentScore = seeds[opponent - 1];
    int roundScore = (opponentScore - seeds[round - 1]).abs();
    roundScores[round - 1] += roundScore;
    currentSeed = nextRound;
    round++;
  }
  return roundScores;
}

