      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];

    for (var combination in winningCombinations) {
      bool allSame = true;
      for (int i = 0; i < 3; i++) {
        if (board[combination[i]][0] != board[combination[i]][2]) {
          allSame = false;
          break;
        }
      }
      if (allSame) {
