      checkTie();
      return;
    }

    int playerIndex = currentTurn;

    bool validMove = false;
    bool trying = true;

    while (trying) {
      if (playerIndex == 0) {
        validMove = true;
      } else {

        validMove = false;

        for (var cell in emptyCells) {
          int i = cell[0];
          int j = cell[1];

          String nextMove = '${names[turn]!}${i.padRight(1)}${j.padRight(1)}';

          print('Move: $nextMove');
          board[i][j] = turn;

          String turnLabel = turn == playerOne ? 'X' : 'O';

          StringBuffer sb = StringBuffer();
          for (int k = 0; k < height; k++) {
            for (int l = 0; l < width; l++) {
              if (board[k][l] == turnLabel) {
                sb.write('*');
              } else if (board[k][l] == ' ') {
                sb.write(' ');
              } else {
                sb.write(board[k][l]);
              }
            }
            sb.write('|');
          }
          sb.write('\n');
          print(sb.toString());

          checkWinner();

          if (!isTerminal) break;

          if (winner == turnLabel) {
            validMove = true;
            break;
          }

          if (emptyCells.isNotEmpty) {
            emptyCells.removeLast();
          }
        }
      }
    }

    if (validMove) {
      switchTurn();
    } else {

      Map<String, int> moves = {};
      for (var cell in emptyCells) {
        int i = cell[0];
