        String move = '${names[turn]!}${i.padRight(1)}${j.padRight(1)}';
        moves[move] = (moves[move] ?? 0) + 1;
      }

      String bestMove = '';
      int bestCount = -1;

      for (var entry in moves.entries) {
        if (entry.value > bestCount ||
            (entry.value == bestCount &&
                (bestMove.isEmpty || entry.key.compareTo(bestMove) < 0))) {
          bestCount = entry.value;
          bestMove = entry.key;
        }
      }

      board[bestMove[0].codeUnitAt(0) - 'A'.codeUnitAt(0) - 1][
          bestMove[1].codeUnitAt(0) - '1'.codeUnitAt(0)] = turn;

      switchTurn();
    }
  }

  void playUntilTerminal() {
    while (!isTerminal) {
      play(currentTurn == 0 ? playerOne : playerTwo);
      switchTurn();
    }
  }

  void gameLoop() {

