        return 'E';
      case SOUTH:
        return 'S';
      case WEST:
        return 'W';
      case NORTH_EAST:
        return 'NE';
      case NORTH_WEST:
        return 'NW';
      case SOUTH_EAST:
        return 'SE';
      case SOUTH_WEST:
        return 'SW';
      default:
        return '?'; 
    }
  }

  List<int> getDirectionOffsets(int dir) {
    switch (dir) {
      case NORTH:
        return [-1, 0];
      case EAST:
        return [0, 1];
      case SOUTH:
        return [1, 0];
      case WEST:
        return [0, -1];
      case NORTH_EAST:
        return [-1, 1];
      case NORTH_WEST:
        return [-1, -1];
      case SOUTH_EAST:
        return [1, 1];
      case SOUTH_WEST:
        return [1, -1];
      default:
        return [-1, -1]; 
    }
  }

  int countOccupied(List<List<bool>> board) {
    int count = 0;
    for (final row in board) {
      for (final cell in row) {
        if (cell) count++;
      }
    }
    return count;
  }

  int countOccupiedDiagonals(List<List<bool>> board) {
    int count = 0;
    const int NUM_DIAGNOALS = 8;
    const int NORTH_EAST = 4;
    const int NORTH_WEST = 5;
    const int SOUTH_EAST = 6;
    const int SOUTH_WEST = 7;
    const int EAST_WEST = 1;

    for (int i = 0; i < NUM_DIAGNOALS; i++) {
      int dir = i & EAST_WEST;
      if (dir == 0) {
        for (int r = 0; r < NUM_ROWS; r++) {
          for (int c = 0; c < NUM_COLUMNS; c++) {
            if (board[r][c] && (i & (1 << (r * NUM_COLUMNS + c))) == 0) {
              count++;
              break;
            }
          }
        }
      } else {
        for (int r = 0; r < NUM_ROWS; r++) {
          for (int c = 0; c < NUM_COLUMNS; c++) {
            if (board[r][c] && (i & (1 << (r * NUM_COLUMNS + c))) == 0) {
              count++;
              break;
            }
          }
        }
      }
    }

    return count;
  }

  List<List<bool>> createBoard(int occupancy) {
    final board = List.generate(NUM_ROWS, (_) => List.filled(NUM_COLUMNS, false));

