    const int NORTH_EAST = 4;
    const int NORTH_WEST = 5;
    const int SOUTH_EAST = 6;
    const int SOUTH_WEST = 7;

    for (int i = 0; i < occupancy; i++) {

      int r = i ~/ NUM_COLUMNS;
      int c = i % NUM_COLUMNS;

      if (r == 0 && c == 0) continue;

      const int dirs = [NORTH, EAST, SOUTH, WEST, NORTH_EAST, NORTH_WEST, SOUTH_EAST, SOUTH_WEST];
      int dir = dirs[i];

      List<int> offs = getDirectionOffsets(dir);
      int nr = r + offs[0], nc = c + offs[1];

      if (nr < 0 || nr >= NUM_ROWS || nc < 0 || nc >= NUM_COLUMNS) continue;

      board[nr][nc] = true;
    }

    return board;
  }

  void printBoard(List<List<bool>> board) {
