    for (final row in board) {
      for (final cell in row) {
        if (cell) {
          String dir = getDirectionName(cell == NORTH ? NORTH : cell == EAST ? EAST : cell == SOUTH ? SOUTH : WEST);
          print('$dir ');
        } else {
          print('  ');
        }
      }
      print('');
    }
  }

  void printBoardInfo(List<List<bool>> board) {
    printBoard(board);
    printOccupiedCount(countOccupied(board));
    printOccupiedDiagonals(countOccupiedDiagonals(board));
    printDirections(board);
    print('');
  }

  List<List<bool>> board = createBoard(20);
  printBoardInfo(board);

  print('=== Random Board ===');
  printBoardInfo(createBoard(20));

  board = createBoard(16);
  printBoardInfo(board);

  print('=== All Occupied ===');
  printBoardInfo(createBoard(NUM_ROWS * NUM_COLUMNS));

  print('=== All Diagonal Occupied ===');
  printBoardInfo(createBoard(NUM_DIAGNOALS));

  Map<String, List<List<bool>>> boardMaps = {
    'All Occupied': createBoard(NUM_ROWS * NUM_COLUMNS),
    'All Diagonal Occupied': createBoard(NUM_DIAGNOALS),
    'Random': createBoard(20),
    'Few Occupied': createBoard(20 - 16),
    'Many Occupied': createBoard(NUM_ROWS * NUM_COLUMNS - 4),
  };

  print('=== Board Maps ===');
  for (final entry in boardMaps.entries) {
    String key = entry.key;
    List<List<bool>> board = entry.value;
    print('$key:');
    printBoardInfo(board);
    print('');
  }
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> morseBits = [0, 0, 1, 1, 1, 0, 1, 0, 1, 0, 0, 0, 1, 1, 1, 0];

  int n = morseBits.length - 1;

  Map<String, int> dp = {};

  String encode(int idx, int len) {
    if (len == 1) {
      return morseBits[idx].toString();
    }
    int half = len ~/ 2;
    String left = encode(idx, half);
    String right = encode(idx + half, len - half);
    return left + right;
  }

  String decode(String s) {
    if (s.isEmpty) {
      return "";
    }
    Map<String, int> map = {'.-': 1, '-...': 3, '-.-.': 2, '.-.': 4};
    StringBuffer sb = StringBuffer();
    String prev = "";
    for (String token in s.split(' ')) {
      if (token.length == 1 && map.containsKey(token)) {
        int count = map[token]!;
        if (prev == token) {
          count += 1;
        }
        for (int i = 0; i < count; i++) {
          sb.write(token);
        }
        prev = token;
      }
    }
    return sb.toString();
  }

  dp[''] = 1;

  for (int i = 0; i <= n; i++) {
    String key = encode(i, i + 1);
    dp[key] = 0;
    for (String prefix in dp.keys) {
      String encoded = prefix + encode(i + 1, i + 1 - prefix.length);
      if (dp.containsKey(encoded)) {
        dp[encoded] = dp[encoded]! + dp[prefix]!;
      }
    }
  }

  print(dp);
  print("Encoded: " + encode(0, n + 1));
  print("Decoded: " + decode(encode(0, n + 1)));
}

