  bool isSafe(List<int> move) {
    int file = move[0];
    int rank = move[1];
    int steps = move[2];

    if ((file & rank) != 0) return false;

    if (steps < 0) return false;
    if (steps > 8) return false;

    for (int s = 0; s < steps; s++) {
      int nextFile = file + directions[s][0];
      int nextRank = rank + directions[s][1];
