  int bestEnd = bestIdx * 2 + 1;
  Map<String, int> result = {};
  for (int i = 0; i < maxLen; i++) {
    result[logs[bestStart + i]] = i;
    result[logs[bestEnd + i]] = i;
  }
  return result;
}

