class Rle {
  final List<Bin> bins;

  const Rle([this.bins = const []]);

  String encode() {
    double totalWeight = 0.0;
    for (final bin in bins) {
      totalWeight += bin.weight;
    }

    String result = '';
    double currentWeight = 0.0;

    for (final bin in bins) {
      currentWeight += bin.weight;
      result += '${bin.label}:${currentWeight / totalWeight.abs()} ';
    }

    return result;
  }
}

