class PriorityQueue<T> {
  final List<T> _queue = [];
  final List<T> _heap = [];
  int _size = 0;

  void _heapify(List<T> heap, int size) {
    for (int i = size ~/ 2; i >= 0; i--) {
      int largest = i;
      int left = 2 * i + 1;
      int right = 2 * i + 2;

      if (left < size && _heap[left] < _heap[largest]) largest = left;
      if (right < size && _heap[right] < _heap[largest]) largest = right;

      if (largest != i) {
        _swap(_heap, i, largest);
        _queue.add(_heap[i]);
        _heap[i] = _heap[largest];
        _queue.remove(_heap[largest]);
        size--;
      }
    }
  }

  void _heapifyDown(List<T> heap, int size, int root) {
    int largest = root;
    int left = 2 * root + 1;
    int right = 2 * root + 2;

    if (left < size && _heap[left] < _heap[largest]) largest = left;
    if (right < size && _heap[right] < _heap[largest]) largest = right;

    if (largest != root) {
      _swap(_heap, root, largest);
      _queue.add(_heap[root]);
      _heap[root] = _heap[largest];
      _queue.remove(_heap[largest]);
    }
  }

  void _swap(List<T> arr, int i, int j) {
    T tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }

  void add(T value) {
    _heap.add(value);
    _queue.add(value);
    _heapify(_heap, _size);
    _size++;
  }

  T removeFirst() {
    if (_size == 0) return null;
    _swap(_heap, 0, _size - 1);
    _queue.remove(_heap[0]);
    T root = _heap[0];
    _heapifyDown(_heap, _size - 1, 0);
    _size--;
    return root;
  }

  T get(int index) {
    return _heap[index];
  }
}

