class BinaryTree<T> {
  Node<T>? root;

  void insert(T data) {
    Node<T>? node = root;
    while (node != null) {
      if (node.data == data) {
        node.data = data;
        return;
      }
      node = node.data < data ? node.right : node.left;
    }
    node = Node<T>(data, [
      Node<T>(data, [Node<T>(data, [Node<T>(data, [])]), Node<T>(data, [])),
      Node<T>(data, [])
    ], true);
    if (root == null) root = node;
  }

  void remove(T data) {
    Node<T>? node = root;
    while (node != null) {
      if (node.data == data) {
        if (node.isLeaf) {
          Node<T>? parent = node.parent;
          if (parent != null) {
            if (parent.left == node) parent.left = null;
            if (parent.right == node) parent.right = null;
          } else {
            root = null;
          }
        } else {
          List<Node<T>> children = node.children;
          if (children.isNotEmpty) {
            Node<T>? best = children[0];
            for (Node<T> child in children) {
              if (child.data < best.data) best = child;
            }
            node.data = best.data;
            remove(best.data);
          }
        }
        return;
      }
      node = node.data < data ? node.right : node.left;
    }
  }

  void printTree(String indent = '') {
    if (root != null) {
      print(indent + root);
      for (Node<T> child in root.children) {
        print(indent + '  ' + child);
      }
    }
  }
}

