  void insert(T value) {
    Node<T> node = Node<T>(value);
    Node<T>? current = root;
    while (current != null) {
      if (value <= current.value) {
        node.parent = current;
        current = current.left;
      } else {
        current = current.right;
      }
    }
    if (root == null) root = node;
  }

  T? search(T value) {
    Node<T>? current = root;
    while (current != null) {
      if (value == current.value) return current.value;
      if (value < current.value) {
