class BinaryHeap<T extends Comparable> {
  List<T> heap = [];
  void heapify(List<T> data, int size) {
    for (int i = 0; i < size; i++) {
      int parent = i;
      int left = (2 * i) + 1;
      int right = (2 * i) + 2;

      if (left < size && data[left] < data[parent]) {
        parent = left;
      }
      if (right < size && data[right] < data[parent]) {
        parent = right;
      }
      if (parent != i) {
        T tmp = data[i];
        data[i] = data[parent];
        data[parent] = tmp;
      }
    }
  }
  void heapInsert(T item) {
    heap.add(item);
    int index = heap.length - 1;

    while (index > 0) {
      int parent = (index - 1) ~/ 2;
      if (item.compareTo(heap[parent]) > 0) {
        heap[index] = heap[parent];
        index = parent;
      } else {
        break;
      }
    }
    heap[index] = item;
  }
  T heapExtract() {
    if (heap.isEmpty) return null;
    T root = heap[0];
    heap[0] = heap.removeLast();
    heapify(heap, heap.length - 1);
    return root;
  }
}

class PriorityQueue<T extends Comparable> implements Queue<T> {
  BinaryHeap<T> heap = BinaryHeap<T>();
  @override
  void add(T item) {
    heap.heapInsert(item);
  }
  @override
  T removeFirst() {
    return heap.heapExtract();
  }
}

