    n + 1,
    (_) => List.filled(target + 1, 0),
  );
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= target; j++) {
      dp[i][j] = dp[i - 1][j];
      if (itemPowers[i - 1] <= j) {
        dp[i][j] = dp[i][j] > dp[i][j - itemPowers[i - 1]] + 1
            ? dp[i][j]
            : dp[i][j - itemPowers[i - 1]] + 1;
        total += dp[i][j];
