void fn0() async {

  Stream<int> numbers(int start, int end) async* {
    for (int i = start; i <= end; i++) {
      yield i;
    }
  }

  Stream<int> evenNumbers() async* {
    yield 0;
    yield 2;
    yield 4;
  }

  Stream<int> oddNumbers() async* {
    yield 1;
    yield 3;
    yield 5;
  }

  Stream<int> combinedStream() async* {
    yield* numbers(1, 3); 
    yield* numbers(4, 6); 
    yield* evenNumbers(); 
    yield* oddNumbers(); 
  }

  await for (var number in combinedStream()) {
    print(number);
  }

  await for (var num in numbers(1, 10)) {
    print(num);
  }

  await for (var n in numbers(1, 10)) {
    await Future.delayed(Duration(milliseconds: 100));
    print(n);
  }
}

