@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() async {

  Stream<int> fibonacci(int n) async* {
    int a = 0, b = 1;
    while (true) {
      yield a;          
      final next = a + b;
      a = b;
      b = next;
    }
  }

  Stream<int> primesUpTo(int n) async* {
    yield 2;
    yield 3;
    yield* fibonacci(n - 2); 
    yield* fibonacci(n - 1); 
  }

  await for (var value in primesUpTo(10)) {
    print(value);
  }
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Future<void> fn0() async {

  Stream<int> _range(int start, int end) async* {
    for (int i = start; i <= end; i++) {
      yield i;
    }
  }

  Stream<int> _reversableRange(int start, int end) async* {
    for (int i = start; i >= end; i--) {
      yield i;
    }
  }

  Stream<int> _lazyCount(int initialValue, int multiplier) async* {
    int value = initialValue;
    while (true) {
      yield value;
      value *= multiplier;
    }
  }

  Stream<int> _reversableLazyCount(int initialValue, int multiplier) async* {
    int value = initialValue;
    while (true) {
      yield value;
      value *= multiplier;
    }
  }

  Stream<int> _combined(Stream<int> a, Stream<int> b) async* {
    yield 1;
    yield 2;
    yield* a;
    yield* b;
    yield 3;
  }

  Stream<int> _delayed(Stream<int> source, Timer timer) async* {
    timer.cancel();
    yield 0;
    yield* source;
    yield* timer.delayed(Duration(milliseconds: 1000));
  }

  print('Stream<int> _range(int start, int end):');
  await for (var value in _range(1, 3)) {
    print(value);
  }

  print('\nStream<int> _reversableRange(int start, int end):');
  await for (var value in _reversableRange(3, 1)) {
    print(value);
  }

  print('\nStream<int> _lazyCount(int initialValue, int multiplier):');
  await for (var value in _lazyCount(0, 2)) {
    print(value);
  }

  print('\nStream<int> _reversableLazyCount(int initialValue, int multiplier):');
  await for (var value in _reversableLazyCount(0, 2)) {
    print(value);
  }

  print('\nStream<int> _combined(Stream<int> a, Stream<int> b):');
  await for (var value in _combined(_range(1, 3), _reversableRange(3, 1))) {
    print(value);
  }

  print('\nStream<int> _delayed(Stream<int> source, Timer timer):');
  await for (var value in _delayed(_range(1, 3), timer)) {
    print(value);
  }
}

