  if (scaleFactor == 0) return baseQuantity;
  int gcd(int a, int b) => b == 0 ? a : gcd(b, a % b);
  int g = gcd(baseQuantity, scaleFactor);
  return (baseQuantity ~/ g) * scaleFactor;
}

