bool fn0(int rows, int cols, int gap) {
  if (rows < 2 || cols < 2) return false;
  if (gap < 0) return false;
  int total = rows * cols;
  int threshold = rows + cols - 2;
  int target = (gap + 1) ~/ 2;
  int lo = 1, hi = total, result = 0;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (mid >= threshold) {
      result = mid;
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }
  if (result >= threshold) {
    return result == target;
  }
  return false;
}

