int fn0(List<int> moduleCoords, int gridSize) {
  var score = 0;
  for (var i = 0; i < moduleCoords.length - 1; i++) {
    var d = (moduleCoords[i] - moduleCoords[i+1]).abs() +
        (moduleCoords[i+1] - moduleCoords[i+2]).abs();
    if (d > gridSize) {
      score += d - gridSize;
    } else if (d == 0) {
      score += 2;
    } else {
      score -= d % gridSize;
    }
  }
  return score;
}

